// Importador CIFRADO de alunos -> /academy/importar/entregas (ADITIVO). Dados AES-256-GCM.
// Uso na VPS: curl raw | docker compose exec -T -e IMPKEY=<chave> engine node -
const crypto=require('crypto');
const ENC={"iv": "0yEg0mwihYMKo2Ze", "tag": "IDTew4RkTMz9Z/NMWdAYvw==", "data": ""};

const KEY=(process.env.IMPKEY||process.argv[2]||'').trim();
if(!/^[0-9a-fA-F]{64}$/.test(KEY)){ console.log('ERRO: IMPKEY ausente/invalida (precisa 64 hex)'); process.exit(1); }
let ALUNOS;
try{
  const dp=crypto.createDecipheriv('aes-256-gcm', Buffer.from(KEY,'hex'), Buffer.from(ENC.iv,'base64'));
  dp.setAuthTag(Buffer.from(ENC.tag,'base64'));
  const out=Buffer.concat([dp.update(Buffer.from(ENC.data,'base64')), dp.final()]);
  ALUNOS=JSON.parse(out.toString('utf8'));
}catch(e){ console.log('ERRO ao decifrar (chave errada?): '+String(e).slice(0,120)); process.exit(1); }
const EKEY=process.env.ENGINE_API_KEY||process.env.MCP_API_KEY||'';
if(!EKEY){ console.log('ERRO: sem ENGINE_API_KEY no container'); process.exit(1); }
const URL='http://127.0.0.1:8080/academy/importar/entregas';
(async()=>{
  const CH=300; let enviados=0, acessos=0, criados=0, lotes=0, falhas=0;
  console.log('alunos a importar: '+ALUNOS.length);
  for(let i=0;i<ALUNOS.length;i+=CH){
    const chunk=ALUNOS.slice(i,i+CH); lotes++;
    try{
      const r=await fetch(URL,{method:'POST',headers:{'content-type':'application/json','x-api-key':EKEY},body:JSON.stringify({alunos:chunk})});
      const j=await r.json().catch(()=>({})); const d=(j&&j.dados&&j.dados.dados)?j.dados.dados:(j.dados||j);
      enviados+=chunk.length; acessos+=(d&&(d.acessos_criados||d.acessos||0))||0; criados+=(d&&(d.alunos_criados||d.criados||0))||0;
      console.log('lote '+lotes+' status '+r.status+' -> '+JSON.stringify(d).slice(0,180));
    }catch(e){ falhas+=chunk.length; console.log('ERRO lote '+lotes+': '+String(e).slice(0,160)); }
  }
  console.log('==== FIM ==== enviados='+enviados+' acessos='+acessos+' novos='+criados+' falhas='+falhas+' total='+ALUNOS.length);
})();
